// Content types for translation context
export type ContentType = 
  | 'devotional' 
  | 'prayer' 
  | 'scripture' 
  | 'teaching' 
  | 'announcement' 
  | 'ui' 
  | 'notification' 
  | 'error' 
  | 'general';

